-- Product taxonomy (reference data, not products). Idempotent.
on conflict (id) do update set parent_id = excluded.parent_id, kind = excluded.kind, name_en = excluded.name_en, name_id = excluded.name_id, path = excluded.path, sort_order = excluded.sort_order;

-- cited exchange rates only (see src/lib/format.ts)
on conflict do nothing;
